{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "An LEA that installs the cameras must have an agreement with local law enforcement covering evidence review and overall enforcement.",
      "rationale": "Conveys the mandatory agreement, responsible LEA, local law enforcement counterpart, and both required subjects. The preceding sentence identifies exterior school-bus cameras."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Unless otherwise authorized by law, only POST-certified or state-commissioned law enforcement officers, including school resource officers, may review the evidence.",
      "rationale": "Preserves the legal exception, exclusive officer qualifications, and inclusion of school resource officers. The opening sentence identifies the evidence-review purpose and relevant violation."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The bill also permits an LEA to authorize school security personnel to review it.",
      "rationale": "Conveys the LEA's discretionary authorization of school security personnel to review the same evidence for violations. The mandatory agreement and concurrent-review statements establish that this authority supplements rather than replaces the agreement."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The LEA may use both review processes at the same time.",
      "rationale": "Expressly conveys concurrent review. Together with the mandatory law-enforcement agreement, this communicates that using school personnel does not displace that agreement."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "It defines “school safety personnel” for this provision as school safety officers, school resource officers, and other LEA employees or contractors whose duties include student safety or campus security.",
      "rationale": "Includes all defined personnel categories, the employment or contracting relationship, the qualifying duties, and the definition's limited application."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The bill would take effect upon becoming law.",
      "rationale": "States the effective-date trigger exactly."
    }
  ]
}
